<script setup lang="ts">
import type {StudentEditData,StudentSaveRequest} from '../api/contracts';import TextField from './TextField.vue';import CodeSelect from './CodeSelect.vue';import JapaneseBirthDateField from './JapaneseBirthDateField.vue';
const props=defineProps<{data:StudentEditData;busy:boolean}>();const emit=defineEmits<{options:[];'update:form':[value:StudentSaveRequest]}>();
function change<K extends keyof StudentSaveRequest>(key:K,value:StudentSaveRequest[K]){emit('update:form',{...props.data.form,[key]:value});}
function classChanged(event:Event){const id=(event.target as HTMLSelectElement).value||null;const c=props.data.classes.find(c=>c.classId===id);emit('update:form',{...props.data.form,classId:id,...(c?{schoolYear:c.schoolYear,gradeCode:c.gradeCode}:{})});}
const contacts=[{key:'addressLine1',id:'REG-009',label:'住所1',limit:90,hint:'45文字まで',required:true},{key:'addressLine2',id:'REG-010',label:'住所2',limit:90,hint:'45文字まで'},{key:'phoneNumber',id:'REG-011',label:'本人電話',limit:40,hint:'入力20／保存16字'},{key:'emailAddress',id:'REG-012',label:'本人メール',limit:120,hint:'60文字まで'}] as const;
</script>
<template><fieldset class="editor-fields" :disabled="busy"><legend class="sr-only">学生情報</legend>
<section class="basic-strip">
<TextField id="REG-002" label="学籍番号" :value="data.form.studentNo" :limit="30" required :readonly="!!data.studentId||!data.permissions.update" hint="15文字まで" @change="change('studentNo',$event)"/>
<TextField id="REG-003" label="氏名" :value="data.form.studentName" :limit="16" required :readonly="!data.permissions.update" hint="8文字まで" @change="change('studentName',$event)"/>
<TextField id="REG-004" label="氏名カナ" :value="data.form.studentNameKana" :limit="72" required :readonly="!data.permissions.update" hint="入力36／保存18字" @change="change('studentNameKana',$event)"/>
<JapaneseBirthDateField :model-value="data.form.birthDateInput" :disabled="!data.permissions.update" @update:model-value="change('birthDateInput',$event)"/>
<label data-field-id="REG-006"><span>性別<span class="required"> 必須</span></span><CodeSelect id="REG-006" :model-value="data.form.genderCode" @update:model-value="change('genderCode',$event||'')" :items="data.codes" category="GENDER" required :disabled="!data.permissions.update"/></label>
</section>
<div class="editor-grid"><section class="editor-section"><h2>住所・連絡先</h2><div class="section-fields">
<TextField id="REG-007" label="郵便番号" :value="data.form.postalCode" :limit="20" required :readonly="!data.permissions.update" @change="change('postalCode',$event)"/>
<label class="field" data-field-id="REG-008"><span class="field-label">都道府県<span class="required"> 必須</span></span><CodeSelect id="REG-008" :model-value="data.form.prefectureCode" @update:model-value="change('prefectureCode',$event||'')" :items="data.codes" category="PREFECTURE" required :disabled="!data.permissions.update"/></label>
<TextField v-for="f in contacts" :key="f.key" :id="f.id" :label="f.label" :value="data.form[f.key]" :limit="f.limit" :hint="f.hint" :required="'required' in f&&f.required" :readonly="!data.permissions.update" @change="change(f.key,$event)"/>
</div><p class="section-hint">本人電話・メール・緊急電話のいずれか1つ以上。</p></section>
<section class="editor-section"><h2>在籍・所属</h2><div class="section-fields">
<label class="field" data-field-id="REG-013"><span class="field-label">入学日<span class="required"> 必須</span></span><input id="REG-013" :value="data.form.admissionDate||''" type="date" required :readonly="!data.permissions.update" @input="change('admissionDate',($event.target as HTMLInputElement).value)" @change="$emit('options')"></label>
<label class="field" data-field-id="REG-014"><span class="field-label">在籍区分<span class="required"> 必須</span></span><CodeSelect id="REG-014" :model-value="data.form.enrollmentStatusCode" @update:model-value="change('enrollmentStatusCode',$event||'');$emit('options')" :items="data.codes" category="ENROLLMENT_STATUS" required :disabled="!data.permissions.update"/></label>
<label class="field" data-field-id="REG-015"><span class="field-label">卒業・退学日<span class="required"> 条件付</span></span><input id="REG-015" :value="data.form.enrollmentEndDate||''" type="date" :required="['03','04'].includes(data.form.enrollmentStatusCode)" :readonly="!data.permissions.update||(['01','02'].includes(data.form.enrollmentStatusCode)&&!data.form.enrollmentEndDate)" @input="change('enrollmentEndDate',($event.target as HTMLInputElement).value)" @change="$emit('options')"></label>
<div class="year-grade"><label data-field-id="REG-016">年度<select id="REG-016" :value="data.form.schoolYear??''" :disabled="!data.permissions.update" @change="change('schoolYear',($event.target as HTMLSelectElement).value?Number(($event.target as HTMLSelectElement).value):null);$emit('options')"><option value="">未指定</option><option v-for="y in Array.from(new Set([...data.years,...(data.form.schoolYear===null?[]:[data.form.schoolYear])])).sort((a,b)=>b-a)" :key="y" :value="y">{{y}}</option></select></label><label data-field-id="REG-017">学年<CodeSelect id="REG-017" :model-value="data.form.gradeCode" @update:model-value="change('gradeCode',$event);$emit('options')" :items="data.codes" category="GRADE" :disabled="!data.permissions.update"/></label></div>
<label class="field" data-field-id="REG-018"><span class="field-label">クラス<span class="required"> 条件付</span></span><select id="REG-018" :value="data.form.classId||''" :disabled="!data.permissions.update" :required="['01','02'].includes(data.form.enrollmentStatusCode)" @change="classChanged"><option value="">未所属</option><option v-for="c in data.classes" :key="c.classId" :value="c.classId" :disabled="!c.selectable&&c.classId!==data.form.classId">{{c.schoolYear}} {{c.gradeName}} {{c.classCode}} {{c.className}} {{c.note}}</option></select></label>
<div class="field" data-field-id="REG-019"><span class="field-label">所属人数・定員</span><span>{{data.classes.find(c=>c.classId===data.form.classId)?.occupancy??'－'}} ／ {{data.classes.find(c=>c.classId===data.form.classId)?.capacity??'制限なし'}}（参考）</span></div>
</div><p class="section-hint">在学・休学はクラス必須。卒業・退学は終了日必須。</p></section>
<div><section class="editor-section"><h2>緊急連絡先</h2><div class="section-fields"><div class="emergency-pair">
<TextField id="REG-020" label="氏名（条件付）" :value="data.form.emergencyContactName" :limit="16" :readonly="!data.permissions.update" hint="8文字まで" @change="change('emergencyContactName',$event)"/>
<label data-field-id="REG-021">続柄（条件付）<CodeSelect id="REG-021" :model-value="data.form.relationshipCode" @update:model-value="change('relationshipCode',$event)" :items="data.codes" category="RELATIONSHIP" :disabled="!data.permissions.update"/></label></div>
<TextField id="REG-022" label="電話（条件付）" :value="data.form.emergencyPhoneNumber" :limit="40" :readonly="!data.permissions.update" @change="change('emergencyPhoneNumber',$event)"/>
</div><p class="section-hint">入力する場合は氏名・続柄・電話すべてが必要です。</p></section>
<section class="editor-section"><h2>備考・確認理由</h2><div class="notes-fields"><label data-field-id="REG-023">備考<small>120文字まで</small><textarea id="REG-023" :value="data.form.remarks||''" @input="change('remarks',($event.target as HTMLTextAreaElement).value)" maxlength="240" :readonly="!data.permissions.update"></textarea></label><label data-field-id="REG-024">確認・変更理由<small>60文字まで</small><textarea id="REG-024" :value="data.form.operationReason||''" @input="change('operationReason',($event.target as HTMLTextAreaElement).value)" maxlength="120" :readonly="!data.permissions.update"></textarea></label></div><p class="section-hint">重複確認の続行・卒業／退学からの区分訂正時に入力。</p></section></div>
</div></fieldset></template>
